void fn0() {


  List<List<int>> graph = [
    [1],
    [2, 3],
    [3],
    [2],
    []
  ];

  List<int> topologicalSort(List<List<int>> graph, int numVertices) {
    List<int> disc = List<int>.filled(numVertices, 0);
    List<int> low = List<int>.filled(numVertices, 0);
    List<int> onStack = List<int>.filled(numVertices, 0);
    List<int> stack = [];

    List<int> topologicalSortResult = [];

    int currentLow = 0;

    for (int i = 0; i < numVertices; i++) {
      if (graph[i].isEmpty) {

        stack.add(i);
        continue;
      }

      if (disc[i] == 0) {

        disc[i] = low[i] = currentLow++;

        stack.add(i);
        onStack[i] = 1;

        for (int j = 0; j < graph[i].length; j++) {
          int neighbor = graph[i][j];

          if (disc[neighbor] == 0) {

            disc[neighbor] = low[neighbor] = currentLow++;

            stack.add(neighbor);
            onStack[neighbor] = 1;
          } else if (onStack[neighbor]) {

            low[i] = low[i] < low[neighbor] ? low[i] : low[neighbor];
          }
        }

        if (low[i] == low[i - 1]) {

          bool hasCycle = true;
          int i2 = 0;

          while (stack.isNotEmpty && i2 < numVertices) {
            int v = stack.removeLast();
            if (v == i) {
              hasCycle = false;
              break;
            }
            i2++;
          }

          if (hasCycle) {
            return topologicalSortResult;
          }
        }
      } else if (onStack[i]) {

        low[i] = low[i] < low[i - 1] ? low[i] : low[i - 1];
      }
    }

    for (int i = 0; i < numVertices; i++) {
      if (disc[i] == 0 && !onStack[i]) {
        stack.add(i);
      }
    }

    while (stack.isNotEmpty) {
      topologicalSortResult.add(stack.removeLast());
    }

    return topologicalSortResult;
  }

  List<int> sorted = topologicalSort(graph, graph.length);

  print('Topological Sort: $sorted');
}

