void dfs(List<List<int>> graph, List<int> disc, List<int> low, List<int> stack, int u, int t) {
  disc[u] = low[u] = t;
  stack.add(u);

  for (int v = 0; v < n; v++) {
    if (graph[u][v] == 1 && disc[v] == 0) {
      dfs(graph, disc, low, stack, v, t + 1);
      low[u] = low[u] < low[v] ? low[u] : low[v];
      if (low[u] >= disc[u]) {
        print('Graph contains a cycle, topological sort not possible.');
        return;
      }
    }
  }
}

