bool search(String text) {
  List<int> dp = List.filled(text.length + 1, 0);
  int n = text.length;

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (text[j] == text[i - 1]) {
        dp[i] = dp[i] > dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }

  if (dp[n] == 0) return false;
  return true;
}

