enum Role {
  admin,
  editor,
  viewer,
  none,
}

extension RoleExtension on Role {
  String get name {
    switch (this) {
      case Role.admin:
        return 'admin';
      case Role.editor:
        return 'editor';
      case Role.viewer:
        return 'viewer';
      case Role.none:
        return 'none';
      default:
        return 'unknown';
    }
  }

  String get description {
    switch (this) {
      case Role.admin:
        return 'Can manage users and perform all actions';
      case Role.editor:
        return 'Can write and delete items';
      case Role.viewer:
        return 'Can read and perform some actions';
      case Role.none:
        return 'Has no permissions';
      default:
        return 'Invalid role';
    }
  }
}

class Permission {
  final String name;
  final String description;
  final String? actor;

  factory Permission.manage_users() {
    return Permission._internal('manage_users', 'Can add, edit, and delete users');
  }

  factory Permission.read() {
    return Permission._internal('read', 'Can view information');
  }

  factory Permission.write() {
    return Permission._internal('write', 'Can modify data');
  }

  factory Permission.delete() {
    return Permission._internal('delete', 'Can remove items');
  }

  Permission._internal(this.name, this.description, [this.actor]);

  @override
  String toString() {
    return 'Permission: $name - $description';
  }
}

class User {
  final String name;
  final Role role;
  final List<Permission> permissions;

  User(this.name, this.role, [this.permissions = const []]);

  void grantPermission(Permission permission) {
    if (role == Role.admin || role == permission.actor) {
      permissions.add(permission);
      print('User $name granted ${permission.name}');
    } else {
      print('User $name cannot grant ${permission.name}');
    }
  }

  bool hasPermission(Permission permission) {
    return permissions.contains(permission);
  }

  @override
  String toString() {
    return 'User $name: ${role.name} with ${permissions.length} permissions';
  }
}

