  const int MOD = 1000000007;


  final int total = _combinations(n, k, items);
  print('Total combinations: $total');
}

int _combinations(int n, int k, List<String> items) {
  if (n == 0 || k == 0 || k > n) return 0;
  if (k == 1) return n;


  int prev = 1;
  int cur = 1;
  for (int i = 1; i <= n - k; i++) {
    prev = cur;
    cur = (cur * (n - i) ~/ (i + 1)) % MOD;
  }
  return prev;
}

