    if (arg == 'A') { items.add('A'); indices.add(0); }
    else if (arg == 'B') { items.add('B'); indices.add(1); }
    else if (arg == 'C') { items.add('C'); indices.add(2); }
    else if (arg == 'D') { items.add('D'); indices.add(3); }
    else if (arg == '-k') { kStr = args[i + 1]; i++; }
    else if (arg == '-items') {
      for (int j = i + 1; j < args.length; j++) {
        String item = args[j];
        if (item != 'A' && item != 'B' && item != 'C' && item != 'D') {
          print('Invalid item: $item');
          return;
        }
        items.add(item);
        indices.add(item == 'A' ? 0 : item == 'B' ? 1 : item == 'C' ? 2 : 3);
      }
      i = j - 1;
    } else {
      print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
      return;
    }
  }

  if (kStr.isNotEmpty) {
    k = int.tryParse(kStr) ?? 0;
    if (k < 0) {
      print('k must be between 0 and n (inclusive). n=${items.length}, k=$k');
      return;
    }
  } else {
    print('No args provided. Using default input: k=${items.length}, items=${items.length}');
  }

  print('Total combinations: ${totalCombinations(items, indices, k)}');
}

int totalCombinations(List<String> items, List<int> indices, int k) {
  if (k <= 0 || k > items.length) return 0;
  if (k == 1) return 1;

  List<List<String>> combinations = [];
  void backtrack(List<String> current, List<int> remaining) {
    if (current.length == k) {
      combinations.add(List.from(current));
      return;
    }
    for (int i = 0; i < remaining.length; i++) {
      if (remaining[i] == 0) continue;
      int nextI = remaining[i] - 1;
      String item = items[nextI];
      current.add(item);
      remaining[i] = nextI;
      backtrack(current, remaining);
      current.removeLast();
      remaining[i] = nextI + 1;
    }
  }

  List<int> remaining = List.generate(items.length, (i) => i + 1);
  backtrack([], remaining);
  return combinations.length;
}

