bool pathExists(Map<int, List<int>> graph, int u, int v) {
  if (!graph.containsKey(u) || !graph.containsKey(v)) return false;
  final List<int> uPath = <int>[];
  final List<int> vPath = <int>[];
  bool hasPath = false;

  void dfs(int node, int target) {
    if (node == target) {
      hasPath = true;
      return;
    }

    for (final int neighbor in graph[node] ?? <int>[]) {
      if (!uPath.contains(neighbor) && !vPath.contains(neighbor)) {
        uPath.add(neighbor);
        dfs(neighbor, target);
      }
    }
  }

  dfs(u, v);
  dfs(v, u);

  return hasPath;
}

void findConnectedComponents(Map<int, List<int>> graph, Set<int> visitedNodes, List<int> currentComponent) {
  if (!graph.containsKey(currentComponent.last)) return;
  visitedNodes.add(currentComponent.last);
  currentComponent.add(currentComponent.last);

  for (final int neighbor in graph[currentComponent.last] ?? <int>[]) {
    if (!visitedNodes.contains(neighbor)) {
      findConnectedComponents(graph, visitedNodes, currentComponent);
    }
  }
}

