    String cleaned = '';
    bool hasDot = false;
    bool hasDash = false;

    for (int i = 0; i < symbol.length; i++) {
      String ch = symbol[i];

      if (ch == '.') {
        cleaned += ch;
        hasDot = true;
      } else if (ch == '-') {
        cleaned += ch;
        hasDash = true;
      } else {
        return [-1, -1];
      }
    }

    if (!hasDot || !hasDash) continue;

    int x1 = 0;
    int y1 = 0;
    int x2 = 0;
    int y2 = 0;

    for (int i = 0; i < cleaned.length; i++) {
      String ch = cleaned[i];

      if (ch == '-') {
        if (i == 0) {
          x1 = i;
        } else {
          x2 = i;
        }
      } else if (ch == '.') {
        if (i == 0) {
          y1 = i;
        } else {
          y2 = i;
        }
      } else {
        return [-1, -1];
      }
    }

    if (x2 < x1 || y2 < y1) continue;

    xs.add(x1);
    xs.add(x2);
    ys.add(y1);
    ys.add(y2);
  }

  if (xs.isEmpty || ys.isEmpty) {
    return [-1, -1];
  }

  Set<List<int>> xSet = {};
  Set<List<int>> ySet = {};

  for (int x in xs) {
    for (int y in ys) {
      xSet.add([x, y]);
    }
  }

  List<int> xsUnique = [];
  List<int> ysUnique = [];

  for (var pt in xSet) {
    if (!xsUnique.contains(pt[0]) && !xsUnique.contains(pt[1])) {
      xsUnique.add(pt[0]);
      xsUnique.add(pt[1]);
    }
  }

  for (var pt in ySet) {
    if (!ysUnique.contains(pt[0]) && !ysUnique.contains(pt[1])) {
      ysUnique.add(pt[0]);
      ysUnique.add(pt[1]);
    }
  }

  int minX = xsUnique[0];
  int maxX = xsUnique[0];
  int minY = ysUnique[0];
  int maxY = ysUnique[0];

  for (var pt in xsUnique) {
    if (pt < minX) minX = pt;
  }
  for (var pt in xsUnique) {
    if (pt > maxX) maxX = pt;
  }
  for (var pt in ysUnique) {
    if (pt < minY) minY = pt;
  }
  for (var pt in ysUnique) {
    if (pt > maxY) maxY = pt;
  }

  int totalArea = (maxX - minX) * (maxY - minY);

  List<int> result = [];
  result.add(totalArea);

  for (var x in xsUnique) {
    for (var y in ysUnique) {
      if (!xSet.contains([x, y])) continue;
      List<int> pt = [x, y];
      result.add(pt[0]);
      result.add(pt[1]);
    }
  }

  result.sort();
  return result;
}

