  List<int> xs = [];
  List<int> ys = [];
  Set<String> seenWalls = {};
  Set<String> validWalls = {'.', '#'};

  for (int r = 0; r < maze.length; r++) {
    for (int c = 0; c < maze[r].length; c++) {
      if (maze[r][c] == '.' && validWalls.contains(maze[r][c])) {
        String key = '$r,$c';
        if (seenWalls.add(key)) {
          tokens.add(key);
          xs.add(r);
          ys.add(c);
        }
      }
    }
  }

  if (tokens.isEmpty) return [];

  List<List<int>> rects = [];
  String prev = '';
  int count = 0;

  for (String token in tokens) {
    if (token == prev) count++;
    else {
      if (count > 0) {
        rects.add([xs[count - 1], ys[count - 1], xs[count] - 1, ys[count] - 1]);
      }
      prev = token;
      count = 1;
    }
  }
  if (count > 0) {
    rects.add([xs[count - 1], ys[count - 1], xs[count] - 1, ys[count] - 1]);
  }

  List<List<int>> unionRects = [];
  for (int i = 0; i < rects.length; i++) {
    for (int j = i + 1; j < rects.length; j++) {
      bool cover = true;
      for (int c = rects[i][2]; c >= rects[j][0] && c >= 0 &&
          c < rects[j][2] && c >= rects[j][0] &&
          rects[i][3] >= rects[j][1] && rects[i][3] <= rects[j][3];
          c--) {
        for (int r = rects[i][1]; r >= rects[j][0] && r >= 0 &&
            r < rects[j][1] && r >= rects[j][0] &&
            rects[i][3] >= rects[j][3] && rects[i][3] <= rects[j][1];
            r--) {
          if (c == rects[i][0] && r == rects[i][3]) {
            cover = false;
            break;
          }
        }
        if (!cover) break;
      }
      if (cover) {
        unionRects.add([
          rects[i][0] < rects[j][0] ? rects[i][0] : rects[j][0],
          rects[i][1] < rects[j][1] ? rects[i][1] : rects[j][1],
          rects[i][2] > rects[j][2] ? rects[i][2] : rects[j][2],
          rects[i][3] > rects[j][3] ? rects[i][3] : rects[j][3]
        ]);
      }
    }
  }

  List<List<int>> uniqueRects = [];
  for (List<int> rect in unionRects) {
    if (uniqueRects.isEmpty ||
        uniqueRects.last[0] != rect[0] ||
        uniqueRects.last[1] != rect[1] ||
        uniqueRects.last[2] != rect[3] ||
        uniqueRects.last[3] != rect[2]) {
      uniqueRects.add(rect);
    }
  }

  List<int> areas = [];
  for (List<int> rect in uniqueRects) {
    areas.add(rect[2] - rect[0] + 1) * (rect[3] - rect[1] + 1);
  }

  List<int> intervals = [];
  for (int i = 0; i < areas.length - 1; i++) {
    int a = areas[i];
    int b = areas[i + 1];
    if (a > 0 && b > 0 && (a < b || b < a)) {
      intervals.add(a < b ? a : b);
    }
  }

  intervals.sort();
  return intervals;
}

