  bool nextZone = true;

  while (i < zones.length) {
    if (nextZone) {
      result.add(-1);
      nextZone = false;
      i++;
      continue;
    }

    int j = i;
    while (j < zones.length && zones[j] == zones[i]) {
      j++;
    }

    final int start = zones[i];
    final int end = zones[j - 1];

    final int duration = end - start;
    final int occupied = j - i;

    if (duration == 0) {
      result.add(-1);
    } else if (duration == 1) {
      result.add(occupied);
    } else {
      result.add(occupied - duration + 1);
    }

    nextZone = true;
    i = j;
  }

  result.add(-1);
  return result;
}

