    String durationStr = parts[1];
    List<String> timeParts = durationStr.split(':');
    if (timeParts.length != 2) continue;
    String startStr = timeParts[0];
    String endStr = timeParts[1];
    int startHour = int.parse(startStr);
    int endHour = int.parse(endStr);
    if (startHour < 0 || endHour > 23) continue;
    List<String> segments = id.split('-');
    String zone = segments[0];
    String room = segments[1];
    List<int> startTimes = [startHour, 0, 0, 0];
    List<int> endTimes = [endHour + 1, 0, 0, 0];
    if (zone == 'PM') {
      startTimes[0] = endTimes[0] + 1;
      endTimes[0] = endHour + 1;
    } else if (zone == 'AM') {
      endTimes[0] = startHour;
    } else {
      continue;
    }
    for (int i = 1; i < 4; i++) {
      if (startTimes[i] > endTimes[i]) {
        continue;
      }
      if (endTimes[i] < startTimes[i]) {
        startTimes[i] = endTimes[i];
      }
    }
    for (int h = startTimes[0]; h <= endTimes[0]; h++) {
      int minutes = startTimes[1];
      if (minutes < 0) minutes = 0;
      if (minutes > 59) minutes = 59;
      if (h < startTimes[2] || h > endTimes[2]) continue;
      if (room.isEmpty) {
        for (int m = minutes; m <= endTimes[1]; m++) {
          if (m < 0) m = 0;
          if (m > 59) m = 59;
          yield h * 60 + m;
        }
      } else {
        for (int m = minutes; m <= endTimes[1]; m++) {
          if (m < 0) m = 0;
          if (m > 59) m = 59;
          if (m == 0 || m == 59) {
            yield h * 60 + m;
          }
        }
      }
    }
  }
  List<int> uniqueTemps = [];
  for (String id in activeIds) {
    List<String> segments = id.split('-');
    String zone = segments[0];
    String room = segments[1];
    if (zone == 'PM' || zone == 'AM') continue;
    uniqueTemps.add(room.isEmpty ? -1 : int.parse(room));
  }
  uniqueTemps.sort();
  return uniqueTemps;
}

