void solveNQueens(int n) {

  List<int> queens = List<int>.filled(n, 0);
  bool solved = false;
  int solutions = 0;

  void placeQueens(int row) {
    for (int col = 0; col < n; col++) {
      if (!isSafe(queens, row, col)) {
        continue;
      }
      queens[row] = col;
      if (row == n - 1) {
        solved = true;
        solutions++;
        print('Solution $solutions');
        for (int i = 0; i < n; i++) {
          String line = List.generate(n, (j) => j == queens[i] ? 'Q ' : '. ').join(' ');
          print(line);
        }
      } else {
        placeQueens(row + 1);
        if (!solved) {
          queens[row] = 0;
        }
      }
    }
  }

  for (int row = 0; row < n; row++) {
    placeQueens(row);
    if (solved) {
      break;
    }
  }

  print('Total solutions: $solutions');
}

