      'pairCount': 0,
      'mashupDuration': 0,
    };
  }

  int left = 0;
  int right = packets.length - 1;
  int maxLen = packets.length;

  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    int windowSum = 0;
    for (int i = 0; i <= mid; i++) {
      windowSum += packets[i];
    }

    if (windowSum <= mtu) {
      int currentLen = mid - left + 1;
      if (currentLen > maxLen) {
        maxLen = currentLen;
      }
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  int pairCount = 0;
  int mashupDuration = 0;
  int totalPackets = 0;

  void search(int start, int end) {
    if (start >= end) return;

    for (int i = start; i <= end; i++) {
      totalPackets += packets[i];
    }

    int prefixSum = 0;
    for (int i = start; i <= end; i++) {
      prefixSum += packets[i];
      if (prefixSum <= mtu) {
        int suffixSum = 0;
        for (int j = end + 1; j >= i; j--) {
          suffixSum += packets[j];
          if (suffixSum <= mtu) {
            pairCount++;
            mashupDuration += prefixSum + suffixSum;
            break;
          }
        }
      }
    }

    search(start, i - 1);
    search(i + 1, end);
  }

  search(0, maxLen - 1);

  return {
    'pairCount': pairCount,
    'mashupDuration': mashupDuration,
    'totalPackets': totalPackets,
  };
}

