  const Quaternion.fromList(List<double> parts)
      : this(parts[0], parts[1], parts[2], parts[3]);

  const Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ, double angle) {
    double cosA = cos(angle / 2);
    double sinA = sin(angle / 2);
    return const Quaternion(
        (axisX * sinA) + (axisY * sinA) + (axisZ * sinA),
        (cosA * axisX) - (sinA * axisY) - (sinA * axisZ),
        (sinA * axisX) + (cosA * axisY) - (sinA * axisZ),
        cosA);
  }

  const Quaternion.fromBasis(List<double> basis)
      : this(basis[0], basis[1], basis[2], basis[3]);

  const Quaternion.fromConjugate(this) : this(this.x, this.y, this.z, -this.w);

  const Quaternion.fromInverse(this) : this(this.x, this.y, this.z, -this.w);

  const Quaternion.fromNormalized(this) : this(
      (x * x) + (y * y) + (z * z) + (w * w),
      (x * y) - (z * w),
      (x * z) + (y * w),
      (x * w) - (y * z));

  const Quaternion.fromAxisAngle(double x, double y, double z, double angle)
      : this.fromAxisAngle(x, y, z, angle);

  const Quaternion.fromBasis(List<double> basis) : this.fromBasis(basis);

  double length() => sqrt(x * x + y * y + z * z + w * w);

  double norm() => length();

  const Quaternion operator +(const other) =>
      const Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(const other) =>
      const Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion operator * (const other) =>
      const Quaternion(
          x * other.w - y * other.z - z * other.y - w * other.x,
          y * other.w - z * other.x - x * other.y - w * other.y,
          z * other.w - x * other.y - y * other.z - w * other.z,
          w * other.w);

  const Quaternion operator * (double scalar) =>
      const Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  const Quaternion conjugate() =>
      const Quaternion(x, y, z, -w);

  const Quaternion inverse() =>
      const Quaternion(x, y, z, -w) * const Quaternion(x, y, z, w);

  const Quaternion rotated(double angle, const axis) => {
    double cosA = cos(angle / 2);
    double sinA = sin(angle / 2);
    return const Quaternion(
        (cosA * x) - (sinA * axis.x) - (sinA * axis.y) - (sinA * axis.z),
