/// Quaternion class represents a 4-tuple (a, b, c, d) that can be used to represent
/// a 4D vector with unit length in the form (a + b*i + c*j + d*k).
class Quaternion {
  double a;
  double b;
  double c;
  double d;

  Quaternion(this.a, this.b, this.c, this.d);

  Quaternion.identity() : this(0.0, 0.0, 0.0, 1.0);

  Quaternion.up()   : this(0.0, 0.0, 1.0, 0.0);
  Quaternion.down() : this(0.0, 0.0, -1.0, 0.0);
  Quaternion.left() : this(1.0, 0.0, 0.0, 0.0);
  Quaternion.right() : this(0.0, 1.0, 0.0, 0.0);

  Quaternion.fromAxisAngle(List<double> axis, double angle) {
    double x = axis[0], y = axis[1], z = axis[2];
    double sin = sin(angle / 2.0);
    double cos = cos(angle / 2.0);
    return Quaternion(
      (x * x * 2.0 * cos + 1.0) * sin,
      (y * x * 2.0 * cos + 1.0) * sin,
      (z * x * 2.0 * cos + 1.0) * sin,
      cos,
    );
  }

  Quaternion operator +(Quaternion other) => Quaternion(a + other.a, b + other.b, c + other.c, d + other.d);

  Quaternion operator -(Quaternion other) => Quaternion(a - other.a, b - other.b, c - other.c, d - other.d);

  Quaternion operator *(Quaternion other) {
    double a = this.a, b = this.b, c = this.c, d = this.d;
    double a2 = other.a, b2 = other.b, c2 = other.c, d2 = other.d;
    double x = b * d2 - a * c2;
    double y = c * d2 - a * b2;
    double z = a * b2 - c * d2;
    double w = a * c2 + b * d2;
    return Quaternion(w, x, y, z);
  }

  Quaternion inverse() => Quaternion(a, b, c, -d);

  Quaternion conjugate() => Quaternion(a, b, c, -d);

  double norm() => sqrt(a * a + b * b + c * c + d * d);

  Quaternion normalized() {
    double n = norm();
    return Quaternion(a / n, b / n, c / n, d / n);
  }

  @override
  String toString() {
    return 'q1 = $a + $b*i + $c*j + $d*k';
  }
}

