      Quaternion(x, y, z, 1.0 / (x * x + y * y + z * z + w * w));

  const Quaternion normalize() {
    double n = norm();
    return (this * (1 / n)).toList();
  }

  const Quaternion rotatePoint(double x, double y, double z) {
    double qxz = x * z + y * w;
    double qyz = y * z + x * w;
    double qxw = x * w + y * z;
    double qyw = y * w + x * z;
    return Quaternion(qxz, qyz, qxw, qyw);
  }

