  for (int i = 0; i < p0.length; i++) {
    String c = p0[i];
    if (c == 'B' || c == 'C' || c == 'D' || c == 'M' || c == 'P') {
      stack.add(c.length);
    } else if (c == 'S') {
      if (stack.isEmpty) return 0.0;
      List<int> segment = [];
      while (stack.isNotEmpty && stack.last > 0) {
        segment.add(stack.removeLast());
      }
      if (segment.isEmpty) {
        stack.add(0);
        continue;
      }
      for (int j = 0; j < segment.length; j++) {
        stack.add(segment[j]);
      }
    } else if (c == 'R') {
      if (stack.length < 2) return 0.0;
      int top = stack.removeLast();
      int second = stack.removeLast();
      stack.addAll([top, second]);
    } else if (c == 'P') {
      if (stack.isEmpty) return 0.0;
      int depth = stack.removeLast();
      for (int j = 0; j < depth; j++) {
        if (stack.isNotEmpty) stack.add(stack.removeLast());
      }
    }
  }
  double score = 0.0;
  for (int value in stack) {
    if (value == 0) {
      score += 2.0;
    } else if (value > 0) {
      score += value.toDouble();
    }
  }
  return score;
}

