      history.add("OPEN");
    } else if (event == "CLOSE") {
      if (open.isNotEmpty) {
        String top = open.removeLast();
        history.add("CLOSE:$top");
      } else {
        history.add("CLOSE:net=0,result=0");
      }
    } else if (event.startsWith("D:")) {
      deck.add(int.parse(event.substring(1)));
    } else if (event.startsWith("C:")) {
      if (deck.isNotEmpty) {
        int drawn = deck.removeLast();
        history.add("D:$drawn");
        if (open.isNotEmpty) {
          String top = open.last;
          history.add("C:$drawn,$top");
          open.removeLast();
        } else {
          history.add("C:$drawn,result=$drawn");
        }
      } else {
        history.add("C:net=0,result=0");
      }
    } else if (event == "FINAL:") {
      if (open.isNotEmpty) {
        history.add("FINAL:net=0,result=0");
      } else {
        int total = 0;
        for (int card in deck) {
          total += card;
        }
        history.add("FINAL:net=$total,result=$total");
      }
    }
  }
  return history;
}

