void fn0() {

  String text = "AABAACAADAABAABA";
  String pattern = "A";

  int n = text.length;
  int m = pattern.length;

  List<List<bool>> lps = List.generate(n, (_) => List<bool>.filled(m, false));
  int length = 0;

  int kmpSearch(String text, String pattern) {
    for (int i = 0; i <= text.length - pattern.length; i++) {
      bool found = true;
      for (int j = 0; j < pattern.length; j++) {
        if (pattern[j] != text[i + j]) {
          found = false;
          break;
        }
      }
      if (found) return i;
    }
    return -1;
  }

  int lpsLength(String pattern) {
    int len = 0;
    int i = 1;

    while (i < pattern.length) {
      if (pattern[i] == pattern[len]) {
        len++;
        lps[len - 1][i - 1] = true;
        i++;
      } else {
        if (len != 0) len = len - 1;
        else {
          i++;
        }
      }
    }
    return len;
  }

  for (int i = 0; i < n; i++) {
    lps[i][0] = true;
  }

  for (int len = 2; len <= m; len++) {
    int i = 0;
    int j = len - 1;

    while (j < n) {
      if (pattern[j] == pattern[i]) {
        lps[i][j] = true;
        i++;
        j++;
      } else if (i != 0) {
        i = lps[i - 1][j - 1];
      } else {
        j++;
      }
    }
  }

  length = lpsLength(pattern);

  print("Text: $text");
  print("Pattern: $pattern");
  print("Pattern length: $m");
  print("\nLPS array for pattern:");
  for (int i = 0; i < m; i++) {
    String row = "";
    for (int j = 0; j < m; j++) {
      row += lps[i][j] ? "A" : " ";
    }
    print(row);
  }
  print("\n");

  int index = kmpSearch(text, pattern);

  if (index == -1) {
    print("Pattern not found in text.");
  } else {
    print("Pattern found at indices: $index");
    print("\nVerification:");
    String verified = text.substring(index, index + pattern.length);
