  int n = votes.length;
  List<int> prefix = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + votes[i] - (i > 0 ? votes[i - 1] : 0);
  }
  int maxLen = 0;
  for (int i = 1; i <= n; i++) {
    if (prefix[i] > threshold) {
      int len = i - 1;
      while (len > 0 && prefix[len] > threshold) len--;
      if (len > maxLen) maxLen = len;
    }
  }
  return maxLen;
}

