int fn0(List<int> p0, int p1) {
  if (p0.isEmpty) return 0;
  List<int> dp = List.filled(p0.length + 1, 0);
  dp[0] = 1;
  for (int i = 1; i <= p0.length; i++) {
    int val = p0[i - 1];
    dp[i] = dp[i - 1] + val > dp[i] ? dp[i - 1] + val : dp[i];
  }
  return dp[p0.length] * p1;
}

