int fn0(List<int> heights, int window) {
  if (heights.isEmpty || window <= 0) {
    return 0;
  }
  final List<int> dp = List<int>.filled(heights.length, 0);
  int maxLen = 0;
  for (int i = 0; i < heights.length; i++) {
    for (int j = 0; j < i; j++) {
      if (heights[i] >= heights[j]) {
        if (i - j > maxLen) {
          maxLen = i - j;
        }
      }
    }
  }
  final int k = maxLen + window;
  final List<int> prefix = List<int>.filled(k, 0);
  for (int i = 0; i < heights.length; i++) {
    for (int j = i; j < heights.length; j++) {
      if (heights[j] >= heights[i]) {
        break;
      }
      final int idx = i - j;
      if (idx >= prefix.length) {
        break;
      }
      prefix[idx] += 1;
    }
  }
  int total = 0;
  for (int i = 0; i < window; i++) {
    total += prefix[i];
  }
  for (int i = window; i < k; i++) {
    total += prefix[i] - prefix[i - window];
  }
  return total;
}

