    'moderator': ['read', 'write', 'delete'],
    'editor': ['read', 'write'],
    'viewer': ['view'],
  };

  final accessMatrix = <String, Map<String, int>>{};

  for (final user in userPermissions.keys) {
    for (final resource in resources.keys) {
      accessMatrix[user] ??= {};
      accessMatrix[user]![resource] = 0;
    }
  }

  for (final user in userPermissions.keys) {
    for (final resource in resources.keys) {
      final permissions = userPermissions[user]!;
      final role = getRoleFor(permissions, resource);
      accessMatrix[user]![resource] = (accessMatrix[user]![resource]! & role) == 0
          ? 0
          : (accessMatrix[user]![resource]! & role) & -role;
    }
  }

  final auditLog = <Map<String, dynamic>>[];

  void logAccess(String user, String resource, int role) {
