String getRoleFor(List<String> permissions, String resource) {
  final roles = <int, String>{
    0: 'viewer',
    1: 'editor',
    2: 'moderator',
    3: 'admin',
  };

  String getRole(List<String> permissions) {
    if (permissions.isEmpty) {
      return 'viewer';
    }
    if (permissions.contains('admin')) {
      return 'admin';
    }
    if (permissions.contains('write') && permissions.length > 1) {
      return 'editor';
    }
    return 'moderator';
  }

  for (final role in roles.keys) {
    final required = roles[role]!;
    if (permissionHierarchy[required]!.containsAll(permissions)) {
      return roles[role]!;
    }
  }

  return getRole(permissions);
}

