int bytesToLittleEndian(List<int> bytes) {
  int result = 0;
  for (int i = 0; i < bytes.length; i++) {
    result = (result << 8) | bytes[i];
  }
  return result;
}

int bytesToBigEndian(List<int> bytes) {
  int result = 0;
  for (int i = bytes.length - 1; i >= 0; i--) {
    result = (result << 8) | bytes[i];
  }
  return result;
}

int hostToNetwork(int value) {
  value &= 0xFFFFFFFF;
  value = (value << 16) | (value >> 16);
  return value;
}

int networkToHost(int value) {
  value &= 0xFFFFFFFF;
  value = (value >> 16) | (value << 16);
  return value;
}

