@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<String>> transactions = [
    ['Milk', 'Bread', 'Butter'],
    ['Milk', 'Bread'],
    ['Bread'],
    ['Milk'],
    ['Bread', 'Butter'],
    ['Milk', 'Butter'],
  ];

  double minSupport = 0.5;
  double minConfidence = 0.7;

  Set<String> items = {};
  for (var trans in transactions) {
    for (var item in trans) {
      if (!items.contains(item)) {
        items.add(item);
      }
    }
  }

  Map<String, int> freq = {};
  for (var trans in transactions) {
    Map<String, int> count = {};
    for (var item in trans) {
      count[item] = (count[item] ?? 0) + 1;
    }
    Set<String> frequent = count.entries.where((e) => e.value >= minSupport).map((e) => e.key).toList();
    for (var item in frequent) {
      freq[item] = (freq[item] ?? 0) + 1;
    }
  }

  Set<String> candidateSet = {};
  String? lastItem;

  bool isFrequent(String item) {
    return freq[item]! >= minSupport;
  }

  bool isFrequent(List<String> items) {
    return items.every((e) => isFrequent(e));
  }

  do {
    Set<String> frequent = {};
    for (var item in items) {
      if (isFrequent(item)) {
        frequent.add(item);
      }
    }
    if (frequent.isEmpty) {
      break;
    }

    Set<String> candidateSet = {};
    for (var item in frequent) {
      for (var newItem in ['Milk', 'Bread', 'Butter']) {
        if (item != newItem && isFrequent(item + newItem)) {
          candidateSet.add(item + newItem);
        }
      }
    }

    if (candidateSet.isEmpty) {
      break;
    }

    Map<String, int> counts = {};
    for (var trans in transactions) {
      for (var item in candidateSet) {
        if (trans.contains(item)) {
          counts[item] = (counts[item] ?? 0) + 1;
        }
      }
    }

    List<String> candidates = candidateSet.toList();
    candidates.sort();

    Map<String, Set<String>> frequentItemsets = {};
    String? currentItem;

    for (var candidate in candidates) {
      if (!frequentItemsets.containsKey(candidate)) {
        frequentItemsets[candidate] = {};
      }

      for (var trans in transactions) {
        if (trans.contains(candidate)) {
          frequentItemsets[candidate]![trans] = (frequentItemsets[candidate]![trans] ?? 0) + 1;
        }
      }
    }

    List<String> itemsToRemove = [];
    for (var entry in frequentItemsets.entries) {
      if (entry.value.length <= 1) {
        itemsToRemove.add(entry.key);
      }
    }

    for (var item in itemsToRemove) {
      if (frequentItemsets.containsKey(item)) {
        frequentItemsets.remove(item);
      }
    }

    items = frequentItemsets.keys.toList();
  } while (items.isNotEmpty);

  print('Frequent Itemsets:');
  print(items.join(' | '));

  Map<String, Set<String>> associationRules = {};
  Set<String> seenItems = {};

  void generateRules(String item, int minSupport) {
    if (!seenItems.contains(item)) {
      seenItems.add(item);

      int support = freq[item]!;
      if (support >= minSupport) {
        String item1 = item;
        String item2 = '';

        for (var trans in transactions) {
          if (trans.contains(item)) {
            for (var newItem in ['Milk', 'Bread', 'Butter']) {
              if (!trans.contains(newItem)) {
                if (item1.isEmpty) {
                  item2 = newItem;
                } else if (newItem.length > item2.length) {
                  item2 = newItem;
                }
              }
            }
          }
        }

        if (item2.isNotEmpty) {
          String rule = '$item1 -> $item2';
          double confidence = (support * minConfidence) / freq[item2]!;
          associationRules[rule] = (associationRules[rule] ?? 0) + 1;
        }
      }
    }
  }

  for (var item in items) {
    generateRules(item, minSupport);
  }

  print('\nAssociation Rules:');
  for (var rule in associationRules.entries) {
    print('${rule.key} (support: ${rule.value / transactions.length}, confidence: ${rule.value * minConfidence / freq[rule.key]}');
  }
}

