class Point<T> {
  final T x;
  final T y;

  const Point(this.x, this.y);

  @override
  String toString() => 'Point($x, $y)';

  @override
  bool operator ==(Object other) =>
      other is Point<T> && x == other.x && y == other.y;

  @override
  int get hashCode => x.hashCode ^ y.hashCode;

  T distance(Point<T> other) {
    double dx = (x - other.x).abs();
    double dy = (y - other.y).abs();
    return sqrt(dx * dx + dy * dy);
  }
}

class Rectangle<T> {
  final Point<T> center;
  final T halfWidth;
  final T halfHeight;

  const Rectangle(
      {required this.center,
        required this.halfWidth,
        required this.halfHeight});

  bool contains(Point<T> p) {
    final dx = p.x - center.x;
    final dy = p.y - center.y;
    return dx * dx + dy * dy <= halfWidth * halfWidth;
  }
}

