  final double y1;
  final double x2;
  final double y2;

  const Rectangle(this.x1, this.y1, this.x2, this.y2);

  @override
  String toString() => 'Rectangle(${x1}, $y1, $x2, $y2)';

  const Rectangle.originTo(double width, double height)
      : this(0, 0, width, height);

  const Rectangle.unit() : this(0, 0, 2, 2);

  const Rectangle.unitLeft() : this(-1, 0, 2, 2);

  const Rectangle.unitRight() : this(1, 0, 2, 2);

  const Rectangle.unitUp() : this(0, 1, 2, 2);

  const Rectangle.unitDown() : this(0, -1, 2, 2);

  const Rectangle.random() {
    final rand = Random(0);
    return Rectangle(
        rand.nextInt(100) - 50, rand.nextInt(100) - 50,
        rand.nextInt(100) - 50 + 100, rand.nextInt(100) - 50 + 100);
  }

  double get area => (x2 - x1) * (y2 - y1);

  double get width => x2 - x1;

  double get height => y2 - y1;

  double get centerX => (x1 + x2) / 2;

  double get centerY => (y1 + y2) / 2;

  bool contains(Point p) =>
      p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2;

  bool contains(Rectangle r) =>
      contains(Point(r.x1, r.y1)) && contains(Point(r.x2, r.y2));

  bool overlaps(Rectangle r) =>
      !(contains(r) || r.contains(this));

  bool intersects(Rectangle r) =>
      !overlaps(r) && r.contains(this) && r.contains(Point(x1, y1));

  const Rectangle.unitIntersection() : this(0, 0, 2, 2);
}

