  while (low <= high) {
    int mid = (low + high) ~/ 2;
    if (readings[mid] >= jump) {
      first = mid;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  low = 0;
  high = readings.length - 1;
  while (low <= high) {
    int mid = (low + high) ~/ 2;
