      high = mid - 1;
    }
  }
  if (first == -1 || last == -1) return "No readings";
  int gap = last - first + 1;
  if (gap <= maxGap) return "Day $first - $last: $gap cm";
  low = first;
  high = last;
  while (low < high) {
    int mid = (low + high) ~/ 2;
    if (readings[mid] >= jump) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
