  ];

  const int k = 3; 

  final int n = points.length;

  final int maxIterations = 100;

  List<int> labels = List.filled(n, 0);

  double distance(List<double> a, List<double> b) {
    double sum = 0;
    for (int i = 0; i < a.length; i++) {
      sum += pow(a[i] - b[i], 2);
    }
    return sqrt(sum);
  }

  void cluster() {

    for (int iter = 0; iter < maxIterations; iter++) {

      final Set<int> assignments = <int>{};

      for (int i = 0; i < n; i++) {

        double minDist = double.infinity;
        int bestCluster = -1;

        for (int c = 0; c < k; c++) {
          final List<int> cluster = List.from(labels);
          cluster[i] = c;

          double dist = 0;
          for (int j = 0; j < n; j++) {
            if (cluster[j] != c) {
              dist += distance(points[i], points[j]);
            }
          }
          if (dist < minDist) {
            minDist = dist;
            bestCluster = c;
          }
        }

        if (bestCluster != -1) {
          assignments.add(bestCluster);
        }
      }

