    ],
  );

  final clusters = List<List<int>>.generate(10, (_) => []);

  var iterations = 0;
  var converged = false;

  while (iterations < 1000 && !converged) {

    final assignments = <int, List<int>>{};
    for (final point in data) {
      final minDist = double.infinity;
      var closest = -1;
      for (var k = 0; k < 10; k++) {
        final dist = point[0] * point[0] + point[1] * point[1] + point[2] * point[2];
        if (dist < minDist) {
          minDist = dist;
          closest = k;
        }
      }
      assignments.putIfAbsent(point[0], () => <int>[closest]);
    }

    final clustersWithNewAssignments = <List<int>>[];
    for (var k = 0; k < 10; k++) {
      final current = assignments[k] ?? <int>[];
      if (current.isEmpty) {
        clustersWithNewAssignments.add([]);
      } else {
        clustersWithNewAssignments.add(List.from(current));
      }
    }

    final newClusters = <int>[];
    for (final points in clustersWithNewAssignments) {
      if (points.length >= 2) {
        newClusters.add(points[0]);
      }
    }

