      int bestCluster = 0;
      for (int j = 0; j < k; j++) {

        final d = (data[i][0] - centroids[j][0]).abs() +
            (data[i][1] - centroids[j][1]).abs();
        if (d < minDist) {
          minDist = d;
          bestCluster = j;
        }
      }

      if (bestCluster == 0) {
        for (int j = 1; j < k; j++) {
          final d = (data[i][0] - centroids[j][0]).abs() +
              (data[i][1] - centroids[j][1]).abs();
          if (d < minDist) {
