void fn0() {

  final rand = Random(0);

  List<List<double>> points = [
    [1.0, 2.0],
    [1.5, 2.5],
    [3.0, 3.0],
    [3.5, 4.0],
    [5.0, 4.5],
    [7.0, 4.5],
    [1.0, 1.0],
  ];

  final int k = 2; 
  final int maxIterations = 100;

  final Set<int> visited = {};

  List<List<int>> clusters = List.generate(k, (_) => []);

  double distance(List<double> p1, List<double> p2) {
    double sum = 0;
    for (int i = 0; i < p1.length; i++) {
      sum += pow(p1[i] - p2[i], 2);
    }
    return sqrt(sum);
  }

  double centroid(List<List<double>> pts) {
    if (pts.isEmpty) return 0.0;
    double x = 0.0, y = 0.0;
    int count = 0;
    for (final pt in pts) {
      x += pt[0];
      y += pt[1];
      count++;
    }
    return x / count, y / count;
  }

  bool isClose(List<List<double>> pts, int i, int j) {
    double d = distance(pts[i], pts[j]);
    if (d == 0) return true;
    for (final pt in pts) {
      if (distance(pt, pts[i]) + distance(pt, pts[j]) == d) return true;
    }
    return false;
  }

  for (int iter = 0; iter < maxIterations; iter++) {

    bool changed = false;

    for (int p = 0; p < points.length; p++) {
      if (!visited.contains(p)) {
        double minDist = double.infinity;
        int bestCluster = -1;
        for (int c = 0; c < clusters.length; c++) {
          for (final pt in clusters[c]) {
            if (distance(points[p], pt) < minDist) {
              minDist = distance(points[p], pt);
              bestCluster = c;
            }
          }
        }
        if (bestCluster != -1) {
          clusters[bestCluster].add(p);
          visited.add(p);
          changed = true;
        }
      }
    }

    if (!changed) break;

    if (iter % 20 == 0) {
      print('Converged in $iter iteration(s).');
    }

    final List<List<double>> centroids = [];
    for (int c = 0; c < clusters.length; c++) {
      centroids.add(centroid(clusters[c]));
    }

    bool converged = true;
    for (int i = 0; i < clusters.length - 1; i++) {
      for (int j = 0; j < clusters.length - 1; j++) {
        if (isClose(centroids, i, j)) {
          converged = false;
          break;
        }
      }
      if (!converged) break;
    }

    if (converged) break;
  }

  for (int c = 0; c < clusters.length; c++) {
    print('Cluster $c:');
    print('  centroid: ${centroids[c]}');
    print('  Points: ${clusters[c]}');
  }
}

