  if (bestCount > 1) {
    for (int j = 0; j < sortedVotes.length; j++) {
      if (sortedVotes[j] == threshold && j != bestIdx) {
        result.add(j);
      }
    }
  }

  int leftIdx = pivot;
  int rightIdx = sortedVotes.length;

  while (leftIdx < rightIdx) {
    int mid = leftIdx + (rightIdx - leftIdx) ~/ 2;
    int cnt = 0;
    int j = mid;

    while (j < sortedVotes.length && sortedVotes[j] == threshold) {
      cnt++;
      j++;
    }

    if (cnt >= pivot) {
      rightIdx = mid;
    } else {
      leftIdx = mid + 1;
    }
  }

  return result;
}

