    yield 100;

    yield* oddNumbers(1, 50);

    yield* timerStream(timer);

    yield 200;

    yield* oddNumbers(51, 100);
  }

  print('Starting combined odd number stream...');
  await for (var number in combinedOddNumberStream(Timer(Duration(seconds: 2)))) {
    print('Odd number: $number');
  }
  print('Stream processing complete.');
}

